import json, sys, glob
d = sys.argv[1]
keys = ('rsc', 'next-router-prefetch', 'next-router-state-tree', 'next-router-segment-prefetch', 'next-url', 'purpose', 'sec-purpose', 'next-test-fetch-priority')
for f in glob.glob(d + '/*.network'):
    for line in open(f):
        e = json.loads(line)
        s = e.get('snapshot', {})
        r = s.get('request', {})
        if not r:
            continue
        hs = {h['name'].lower(): h['value'] for h in r.get('headers', [])}
        print(s.get('startedDateTime', '')[11:23], r.get('method'), r.get('url')[:150], s.get('response', {}).get('status'), {k: v[:60] for k, v in hs.items() if k in keys or k.startswith('next-')})

