// SPDX-License-Identifier: Apache-2.0
// Scratch probe (not committed): load each path, wait, and print every request with RSC markers.
import { chromium } from 'playwright-core';
import { readdirSync } from 'node:fs';
import { homedir } from 'node:os';

const base = process.argv[2];
const paths = process.argv.slice(3);
const cache = `${homedir()}/Library/Caches/ms-playwright`;
const dir = readdirSync(cache).find((d) => d.startsWith('chromium-'));
const exe = `${cache}/${dir}/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing`;
const browser = await chromium.launch({ executablePath: exe });
for (const p of paths) {
  const context = await browser.newContext();
  const page = await context.newPage();
  const lines = [];
  context.on('request', (r) => {
    const u = new URL(r.url());
    if (u.pathname.includes('/_next/static')) return;
    const h = r.headers();
    const marks = Object.keys(h).filter((k) => k === 'rsc' || k.startsWith('next-'));
    lines.push(`  ${r.method()} ${u.pathname}${u.search} ${marks.map((k) => `${k}=${h[k].slice(0, 40)}`).join(' ')}`);
  });
  await page.goto(base + p, { waitUntil: 'load' });
  await page.waitForTimeout(6000);
  console.log(`== ${p}`);
  console.log(lines.join('\n'));
  await context.close();
}
await browser.close();

